/* Inventory controls integrated with the shared workflow workbench. */
'use strict';
const Control={names:{OPEN:'盘点中',SUBMITTED:'待审批',APPROVED:'已批准',REJECTED:'已驳回',NEW:'待处理',INVESTIGATING:'调查中',PENDING:'待审批',RESOLVED:'已处理',CLOSED:'已关闭',DRAFT:'草稿',APPLIED:'已生效',MATCH:'一致',LOSS:'盘亏',GAIN:'盘盈',WEIGHT:'重量差异',LOCATION:'货位不符',DUPLICATE:'重复盘点',UNVERIFIED_MOVEMENT:'流转待核验',RECONCILED_MOVEMENT:'流转已核验',REMOVED_BY_FLOW:'正常流转移出'},can:p=>Business.can(p),async list(route,title,create,detail){const r=await API.request('/'+route);Business.open(title,`${create?`<button id="control-new" class="button primary">${create.label}</button>`:''}${this.table(r.items,['code','status','created_at'])}`);if(create){$('control-new').disabled=!this.can(create.permission);$('control-new').onclick=()=>create.action().catch(e=>notify(e.message));}document.querySelectorAll('[data-control-id]').forEach(b=>b.onclick=()=>detail(b.dataset.controlId).catch(e=>notify(e.message)));},table(rows,fields){const names={code:'单号',status:'状态',created_at:'时间',bundle_no:'捆包编号',finding:'盘点结果',opening:'快照吨数',closing:'账面吨数',actual_weight:'实盘吨数',difference:'差异吨数',actual_location:'实盘货位',expected_location:'账面货位',category:'异常类型',responsible_name:'责任人员'};return `<div class="business-table"><table><thead><tr>${fields.map(k=>`<th>${names[k]||k}</th>`).join('')}<th>明细</th></tr></thead><tbody>${rows.map(x=>`<tr>${fields.map(k=>`<td>${k==='status'?UI.status(x[k],'approval',this.names[x[k]]||x[k]):esc(/(?:^weight$|_weight$|_delta$|^difference$|_net$)/.test(k)?Tonnes.format(x[k]):((this.names[x[k]]||x[k])??'—'))}</td>`).join('')}<td>${x.id?`<button class="detail-button" data-control-id="${x.id}">查看</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;},async post(url,body){return API.request(url,{method:'POST',body});},async stocktakes(){return this.list('stocktakes','盘点计划与任务',{label:'新建盘点任务',permission:'stocktake:write',action:()=>this.countForm()},id=>this.count(id));},
 async countForm(){const m=await Business.load();const opt=(name,key,rows,empty=false)=>`<label>${name}<select name="${key}">${Business.options(rows,undefined,rows[0]?.name?'name':'code',empty)}</select></label>`;Flow.form('新建独立快照盘点',opt('项目','project_id',m.projects)+opt('仓库（必选）','warehouse_id',m.warehouses)+opt('堆场（可选）','yard_id',m.yards,true)+opt('货位（可选）','location_id',m.locations,true)+opt('生产批次（可选）','batch_id',m.batches,true)+'<p>快照覆盖厂内实物，包括已锁定、已装车未正式离场库存。指定人员由当前账号承担；服务器保存独立基准版本。</p>',async b=>{const d=await this.post('/stocktakes',b);await this.count(d.id);});},
 async count(id){const d=await API.request('/stocktakes/'+id),r=d.report;Business.open('盘点 · '+d.code,`<a class="button secondary" href="/stock-map?project_id=${d.project_id}&amp;warehouse_id=${d.warehouse_id}&amp;stocktake_id=${d.id}">按本任务范围查看实时地图（可再选区域）</a><p>地图为实时分布，不替代本单冻结快照与流转对账。</p><p>状态：${esc(this.names[d.status])} · 第${d.current_pass}轮 · 快照版本${d.snapshot_version}<br>基准：${esc(d.snapshot_at)} / 库存版本${esc(d.snapshot_revision)}<br>快照${esc(r.opening_weight)}吨 + 流转${esc(r.movement_net)}吨 = 账面${esc(r.closing_weight)}吨；折算实盘${esc(r.rolled_count_weight)}吨，差异${esc(r.difference)}吨。</p><div class="business-toolbar">${d.status==='OPEN'&&this.can('stocktake:write')?'<button id="count-record" class="button primary">逐捆录入</button><button id="count-import" class="button secondary">Excel实盘导入</button><button data-count-action="submit" class="button secondary">提交结果审批</button>':''}${['OPEN','REJECTED'].includes(d.status)&&this.can('stocktake:write')?'<button data-count-action="recount" class="button secondary">开启复盘（保留前轮）</button>':''}${d.status==='SUBMITTED'&&this.can('stocktake:review')?'<button data-count-action="approve" class="button primary">独立批准盘点结果</button><button data-count-action="reject" class="button secondary">驳回复盘</button>':''}</div><input type="hidden" id="count-note">${d.status==='OPEN'&&this.can('stocktake:review')?'<label>需核验的流转捆包编号<input id="count-reconcile-no"></label><button class="button secondary" data-count-action="reconcile">核验该捆盘点期间流转</button>':''}<p id="count-error" class="error"></p>${this.table(r.rows,['bundle_no','finding','opening','closing','actual_weight','difference','expected_location','actual_location'])}<h3>盘点期间业务流水（实物变动单位：吨）</h3><ol>${d.movements.map(x=>`<li>${esc(x.occurred_at)} · ${esc(x.bundle_no)} · ${esc(x.event_type)} · ${esc(Tonnes.format(x.physical_delta))} · ${esc(x.document_code||'关联流水')}</li>`).join('')}</ol><h3>盘点操作历史</h3><ol>${d.steps.map(x=>`<li>${esc(x.occurred_at)} · ${esc(x.action)} · ${esc(x.note)}</li>`).join('')}</ol><div id="flow-attachments"></div>`);if($('count-record'))$('count-record').onclick=()=>this.recordForm(d).catch(e=>notify(e.message));if($('count-import'))$('count-import').onclick=()=>this.countImport(d).catch(e=>notify(e.message));document.querySelectorAll('[data-count-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await this.post('/stocktakes/'+id+'/'+b.dataset.countAction,{version:d.version,note:$('count-note').value,bundle_no:$('count-reconcile-no')?.value});await this.count(id);}catch(e){$('count-error').textContent=e.message;b.disabled=false;}});await Flow.attachments('stocktakes',id,'stocktake:write');},
 async recordForm(d){const m=await Business.load();Flow.form('逐捆实盘登记',Flow.field('捆包编号','bundle_no','text','','required')+`<label>实际货位<select name="actual_location_id">${Business.options(m.locations.filter(x=>x.warehouse_id===d.warehouse_id))}</select></label>`+Flow.field('实盘净重（吨）','actual_weight','text','','required')+Flow.field('说明','remark'),async b=>{await this.post('/stocktakes/'+d.id+'/observations',{version:d.version,entries:[b]});await this.count(d.id);});},
 async countImport(d){Business.open('Excel实盘 · 整批校验',`<button id="count-template" class="button secondary">下载盘点模板</button><label>选择XLSX（512KiB，最多500行）<input id="count-file" type="file" accept=".xlsx"></label><button id="count-preview" class="button primary">校验预览</button><p id="count-import-error" class="error"></p><div id="count-preview-data"></div><button id="count-save" class="button primary" disabled>保存整批实盘（不改库存）</button>`);let preview=null;$('count-file').onchange=()=>{preview=null;$('count-save').disabled=true;};$('count-template').onclick=()=>this.download('/stocktakes/'+d.id+'/template','盘点模板.xlsx').catch(e=>notify(e.message));$('count-preview').onclick=async()=>{try{const f=$('count-file').files[0];if(!f||f.size>524288)throw Error('请选择512KiB以内XLSX');const raw=new Uint8Array(await f.arrayBuffer());let text='';for(const x of raw)text+=String.fromCharCode(x);preview=await this.post('/stocktakes/'+d.id+'/import-preview',{file_base64:btoa(text)});$('count-preview-data').textContent=preview.valid?'校验通过，共'+preview.entries.length+'行':preview.errors.map(x=>'第'+x.row+'行：'+x.message).join('；');$('count-save').disabled=!preview.valid;}catch(e){$('count-import-error').textContent=e.message;}};$('count-save').onclick=async e=>{e.target.disabled=true;try{await this.post('/stocktakes/'+d.id+'/observations',{version:preview.version,entries:preview.entries,source:'EXCEL'});await this.count(d.id);}catch(err){$('count-import-error').textContent=err.message;e.target.disabled=false;}};},
 async download(url,name,body){const r=await API.request(url,{binary:true,...(body?{method:'POST',body}:{})}),u=URL.createObjectURL(r.blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
};
const v24Menu=Business.menu.bind(Business);Business.menu=function(){v24Menu();const area=document.querySelector('.business-menu');for(const [label,permission,method] of [['库存盘点','stocktake:read','stocktakes'],['库存调整审批','adjust:read','adjustments'],['统计报表','report:read','reports']]){const b=document.createElement('button');b.className='button secondary';b.textContent=label;b.disabled=!Control.can(permission);b.onclick=()=>Control[method]().catch(e=>notify(e.message));area.append(b);}};

Object.assign(Control.names,{RESTORE:'反向恢复'});
Object.assign(Control,{
 async adjustments(){return this.list('adjustments','库存调整与独立审批',null,id=>this.adjustment(id));},
 async adjustment(id){const d=await API.request('/adjustments/'+id),m=await Business.load(),loc=id=>m.locations.find(x=>x.id===id)?.code||'—';Business.open('调整单 · '+d.code,`<p>状态${esc(this.names[d.status])} · 原因${esc(d.reason)}<br>原始入库单、流水和档案原始净重保留；这里只更正当前库存余额投影。</p><div class="business-table"><table><thead><tr><th>捆包</th><th>类型</th><th>原净重</th><th>新净重</th><th>原货位</th><th>新货位</th></tr></thead><tbody>${d.lines.map(x=>`<tr><td>${esc(x.bundle_no)}</td><td>${esc(this.names[x.kind])}</td><td>${esc(x.before_data.net_weight||'未建档')}</td><td>${esc(x.after_data.net_weight)}</td><td>${esc(loc(x.before_data.location_id))}</td><td>${esc(loc(x.after_data.location_id))}</td></tr>`).join('')}</tbody></table></div><input type="hidden" id="adjust-note"><div class="business-toolbar">${d.status==='DRAFT'&&this.can('adjust:write')?'<button data-adjust-action="submit" class="button primary">提交审批</button>':''}${d.status==='PENDING'&&this.can('adjust:approve')?'<button data-adjust-action="approve" class="button primary">独立批准并原子生效</button><button data-adjust-action="reject" class="button secondary">驳回</button>':''}${d.status==='APPLIED'&&this.can('adjust:write')?'<button id="adjust-reverse" class="button secondary">创建新的授权反向单</button>':''}</div><p id="adjust-error" class="error"></p><ol>${d.steps.map(x=>`<li>${esc(x.occurred_at)} · ${esc(x.actor_name)} · ${esc(x.note)}</li>`).join('')}</ol><div id="flow-attachments"></div>`);document.querySelectorAll('[data-adjust-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await this.post('/adjustments/'+id+'/'+b.dataset.adjustAction,{version:d.version,note:$('adjust-note').value});await this.adjustment(id);await render();}catch(e){$('adjust-error').textContent=e.message;b.disabled=false;}});if($('adjust-reverse'))$('adjust-reverse').onclick=async()=>{try{const r=await this.post('/adjustments/'+id+'/reverse',{exception_id:d.exception_id,reason:$('adjust-note').value});await this.adjustment(r.id);}catch(e){$('adjust-error').textContent=e.message;}};await Flow.attachments('adjustments',id,'adjust:write');}
});

Object.assign(Control.names,Flow.names,{INBOUND:'生产入库',OUTBOUND:'正式离场',REVERSAL:'实物退回',SCOPE_TRANSFER:'范围流转',OPENING_BALANCE:'开账余额',ADJUST_GAIN:'批准盘盈',ADJUST_LOSS:'批准盘亏',ADJUST_WEIGHT:'重量调整',ADJUST_LOCATION:'位置纠错',ADJUST_RESTORE:'反向恢复'});
Control.reportTypes={daily:'阴极铜库存日报',monthly:'阴极铜库存月报',allocations:'客户库存分配统计',flows:'生产入库及正式出库统计',samples:'取样检验统计',vehicles:'车辆装车及离场统计',locations:'货位库存分布',stocktakes:'月度库存盘点报告',exceptions:'异常及调整汇总'};
Control.reportLabels={period:'期间',opening_weight:'期初实物（吨）',closing_weight:'期末实物（吨）',inbound_weight:'生产入库（吨）',outbound_weight:'正式离场（吨）',returned_weight:'返场冲销（吨）',adjustment_net:'调整净额（吨）',transfer_net:'范围/开账流转（吨）',reconciliation_difference:'勾稽差额（吨）',physical_weight:'实物（吨）',locked_weight:'锁定（吨）',available_weight:'可用（吨）',physical_delta:'变动（吨）',difference:'盘差（吨）',rolled_count_weight:'折算实盘（吨）',dimension:'维度',bundles:'捆数',bundle_no:'捆包编号',code:'单号',type:'类型',kind:'类别',status:'状态',confirmed_at:'记账/确认时间',document_code:'关联单号',sample_date:'取样日期',agency:'取样机构',registered_at:'登记时间',result_at:'检验时间',result:'结果',vehicle_no:'车辆',loading_completed_at:'装车完成',outbound_code:'出库单',departure_confirmed_at:'正式离场确认',actual_departure_at:'安保观察时间',reversed_at:'冲销确认',created_at:'创建时间',approved_at:'批准时间',closed_at:'关闭时间',reason:'原因',category:'异常类型'};
Control.reportTable=function(rows){if(!rows.length)return '<p>当前截止时间与授权筛选范围内暂无记录。</p>';const fields=[...new Set(rows.flatMap(x=>Object.keys(x)))];return `<div class="business-table"><table><thead><tr>${fields.map(k=>`<th>${esc(this.reportLabels[k]||k)}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr>${fields.map(k=>`<td>${esc(/(?:^weight$|_weight$|_delta$|^difference$|_net$)/.test(k)?Tonnes.format(x[k]):this.names[x[k]]||x[k]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;};
Control.reports=async function(){return Reports463.render();};
Control.showReport=async function(b){const query=new URLSearchParams(Object.entries(b).filter(([,v])=>v)),r=await API.request('/reports?'+query);$('report-result').innerHTML=`<h3>${esc(r.title)}</h3><p class="dialog-notice">${esc(r.notice)}</p><p>${esc(r.document_scope_notice)}<br>截止${esc(r.window.end)}，库存版本${esc(r.window.end_revision)}</p><p>期初${esc(Tonnes.format(r.summary.opening_weight))} + 入库${esc(Tonnes.format(r.summary.inbound_weight))} − 正式出库${esc(Tonnes.format(r.summary.outbound_weight))} + 返场${esc(Tonnes.format(r.summary.returned_weight))} + 调整${esc(Tonnes.format(r.summary.adjustment_net))} + 范围流转${esc(Tonnes.format(r.summary.transfer_net))} + 开账${esc(Tonnes.format(r.summary.opening_import))} = 期末${esc(Tonnes.format(r.summary.closing_weight))}吨；勾稽差额${esc(Tonnes.format(r.summary.reconciliation_difference))}吨。</p><button id="report-export" class="button secondary" ${this.can('inventory:export')?'':'disabled'}>导出当前截止版本 Excel</button>${this.reportTable(r.rows)}`;$('report-export').onclick=()=>this.download('/reports/export','穆松尼_'+r.title+'.xlsx',{...b,as_of:r.window.end}).catch(e=>notify(e.message));};
